// static
bool WakeLockInstanceStubDispatch::AcceptWithResponder(
    WakeLockInstance* impl,
    mojo::Message* message,
    std::unique_ptr<mojo::MessageReceiverWithStatus> responder) {
  [[maybe_unused]] const bool message_is_sync =
      message->has_flag(mojo::Message::kFlagIsSync);
  [[maybe_unused]] const uint64_t request_id = message->request_id();
  switch (message->header()->name) {
    case internal::kWakeLockInstance_Init_Name: {

      internal::WakeLockInstance_Init_Params_Data* params =
          reinterpret_cast<
              internal::WakeLockInstance_Init_Params_Data*>(
                  message->mutable_payload());
      
      
      // Validation for WakeLockInstance.0
      bool success = true;
      ::mojo::PendingRemote<WakeLockHost> p_host_remote{};
      WakeLockInstance_Init_ParamsDataView input_data_view(params, message);
      
      if (success) {
        p_host_remote =
            input_data_view.TakeHostRemote<decltype(p_host_remote)>();
      }
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            WakeLockInstance::Name_, 0, false);
        return false;
      }
      WakeLockInstance::InitCallback callback =
          WakeLockInstance_Init_ProxyToResponder::CreateCallback(
              *message, std::move(responder));
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->Init(        
        std::move(p_host_remote), std::move(callback));
      return true;
    }
  }
  return false;
}
