void WakeLockHostAsyncWaiter::AcquirePartialWakeLock(
    bool* out_result) {
  base::RunLoop loop;
  proxy_->AcquirePartialWakeLock(
      base::BindOnce(
          [](base::RunLoop* loop,
             bool* out_result
,
             bool result) {*out_result = std::move(result);
            loop->Quit();
          },
          &loop,
          out_result));
  loop.Run();
}

bool WakeLockHostAsyncWaiter::AcquirePartialWakeLock(
    ) {
  bool async_wait_result;
  AcquirePartialWakeLock(&async_wait_result);
  return async_wait_result;
}

void WakeLockHostAsyncWaiter::ReleasePartialWakeLock(
    bool* out_result) {
  base::RunLoop loop;
  proxy_->ReleasePartialWakeLock(
      base::BindOnce(
          [](base::RunLoop* loop,
             bool* out_result
,
             bool result) {*out_result = std::move(result);
            loop->Quit();
          },
          &loop,
          out_result));
  loop.Run();
}

bool WakeLockHostAsyncWaiter::ReleasePartialWakeLock(
    ) {
  bool async_wait_result;
  ReleasePartialWakeLock(&async_wait_result);
  return async_wait_result;
}




